def paths() -> List[str]:
    """Ścieżki wszystkich wbudowanych szablonów (diagnostyka/testy)."""
    return sorted(DATA)


def template_text(rel: str) -> Optional[str]:
    """Treść szablonu z danych wbudowanych (None, gdy go tu nie ma)."""
    blob = DATA.get(rel)
    if blob is None:
        return None
    return zlib.decompress(base64.b64decode(blob)).decode("utf-8", errors="replace")
